assert.ok(universalJan.events.filter(e=>e.lead==='Shreya'&&e.kind==='source-scene'&&e.episode==='02').every(e=>e.state==='approved-prose'),'All Shreya source scenes must have approved badges');
assert.ok(universalJan.events.find(e=>e.scene==='SR03'&&e.lead==='Shreya')?.status.includes('author-approved')||universalJan.events.find(e=>e.scene==='SR03'&&e.lead==='Shreya')?.status.includes('Author-approved'),'Episode 02 approval supersedes older SR03 review label without inventing prose');
assert.ok(sourcePlanning.includes('Different helpers:'),'Shreya Planning must distinguish society Chintu and station chai wala');
assert.ok(sourcePlanning.includes("shreyaEpisode03Proposal.reviewBeatSequence.filter(slot=>!['SR10','S03-01','SR11'].includes(slot.id))"),'Shreya completed written scenes moved out of remaining plot cards without losing original numbering');
assert.ok(sourcePlanning.includes('shreyaEpisode03Proposal.parkedFutureEncounters.find'),'UI must explicitly render held inmates in Beat 5');
assert.ok(!sourcePlanning.includes('<strong>Date:</strong> 3 January 2026'),'UI must not show superseded active date');
assert.ok(universalFuture.events.filter(e=>e.episode==='01').every(e=>e.date===null),'Undated prologue must not be silently placed on Jan 1');
assert.equal(universalDhika.episodesIndexed,41,'All Dhika episodes must be indexed');
assert.equal(new Set(universalDhika.events.map(e=>e.episode)).size,41,'Dhika episode index incomplete');
for(let day=1;day<=11;day++)assert.ok(universalDhika.events.some(e=>e.storyDay===day&&e.date===new Date(Date.UTC(2026,0,day)).toISOString().slice(0,10)),'Dhika story Day '+day+' misaligned');
const earlyDhika=universalDhika.events.filter(e=>e.episode==='EP04');
assert.ok(earlyDhika.some(e=>e.date==='2026-01-01')&&earlyDhika.some(e=>e.date==='2026-01-02'),'Dhika EP04 must straddle Day 1/Day 2');
const rootCorpus=JSON.parse(readFileSync(resolve(root,'../data/corpus.json'),'utf8'));
assert.ok(universalJan.events.some(e=>e.id==='ep03-ankita-scene04'&&e.date==='2026-01-01'),'Rohit intro must be Jan 1, before any first look');
assert.equal(universalJan.events.filter(e=>e.id.startsWith('ep03-ankita-scene')).length,8,'Ankita eight EP03 scenes indexed in Jan1 timeline');
assert.ok(universalJan.events.some(e=>e.id==='ep03-ankita-scene08'&&e.start==='18:10'&&e.end==='18:25'&&e.source==='episode-03-ankita-scene-08-prose-draft.json'&&e.reader?.scene==='08'),'Rinku Scene08 prose must remain Jan1 18:10–18:25');
assert.equal(universalFuture.events.filter(e=>e.id.startsWith('date-pending-ankita-')).length,0,'Discarded old home followups must not appear as active timeline events');
assert.deepEqual(universalFuture.events.filter(e=>e.id.startsWith('future-ankita-rohit-')).map(e=>e.date),[null,null],'Earlier Rohit drafts are retained as unscheduled historical records, not duplicate Jan2 events');
assert.deepEqual(universalFuture.events.filter(e=>e.id.startsWith('ep04-chotu-ankita-rohit-')).map(e=>e.date),['2026-01-02','2026-01-02'],'Updated Rohit accident and willing follow-up are both reserved for Jan2 review');
for(const event of universalDhika.events){
 const ep=rootCorpus.episodes.find(x=>x.id===event.episode);
 assert.ok(ep&&ep.lines[event.firstLineIndex],'Invalid Dhika paragraph pointer '+event.id);
 assert.ok(event.lastLineIndex<ep.lines.length,'Dhika range extends beyond original source '+event.id);
 if(event.arcRelativeDay)assert.equal(event.date,null,'Arc-relative Day 1 must never reset to Jan 1');
}
